    SELECT MIN(id)
    FROM pages
    WHERE `group` = 'blog'
      AND slug = @blog_slug
);

UPDATE pages
SET category_id = NULL,
    `group` = 'blog',
    subgroup = NULL,
    title = '50 knjiga koje svatko treba pročitati barem jednom u životu',
    short_description = 'Od bezvremenskih klasika do velikih epova: odabrali smo 50 knjiga koje vrijedi pročitati barem jednom, uz izdanja dostupna u Zuzi ponudi.',
    description = @blog_description,
    meta_title = '50 knjiga koje svatko treba pročitati | Zuzi blog',
    meta_description = 'Otkrijte 50 klasika svjetske književnosti koje vrijedi pročitati barem jednom i pronađite dostupna izdanja u antikvarijatu i knjižari Zuzi.',
