    image = 'media/img/blog/50-knjiga-koje-svatko-treba-procitati.jpg',
    publish_date = @published_at,
    featured = 0,
    related_products = @related_products,
    status = 1,
    updated_at = NOW()
WHERE id = @blog_id;

