SET @blog_id := COALESCE(@blog_id, LAST_INSERT_ID());
COMMIT;

SELECT
    @blog_id AS blog_id,
    @blog_slug AS slug,
    @active_products_found AS active_related_products,
    CASE
        WHEN @active_products_found = 50 THEN 'OK'
        ELSE 'WARNING: expected 50 active products with quantity > 0'
    END AS product_check;
